import { test } from "node:test";
import assert from "node:assert/strict";
import { shouldPageStalledDispatch } from "../src/alerts.ts";

test("pages when queued work, no dispatches, and free capacity", () => {
  assert.equal(shouldPageStalledDispatch({ queued: 10, dispatchedInWindow: 0, freeCapacity: 5 }), true);
});

test("does not page when the queue is empty", () => {
  assert.equal(shouldPageStalledDispatch({ queued: 0, dispatchedInWindow: 0, freeCapacity: 5 }), false);
});

test("does not page when the fleet is fully saturated", () => {
  assert.equal(shouldPageStalledDispatch({ queued: 10, dispatchedInWindow: 0, freeCapacity: 0 }), false);
});

test("does not page when dispatch is still happening", () => {
  assert.equal(shouldPageStalledDispatch({ queued: 10, dispatchedInWindow: 3, freeCapacity: 5 }), false);
});

